    @Test
    void carrinhoVazioRetornaPedidoInvalido() {
        String json = """
                {
                  "itens": [],
                  "modalidadeEntrega": "ECONOMICA",
                  "formaPagamento": "PIX",
                  "nivelClube": "BRONZE",
                  "regiao": "SUL"
                }
                """;
        ResponseEntity<ErroResponse> resposta = restTemplate.postForEntity(
                "http://localhost:" + port + "/checkout/resumo",
